 async void CheckConnection_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var r=Current();MainTabs.SelectedItem=CommandsTab;OutputBox.Text="Проверка подключения к "+r.Host+"…";try{OutputBox.Text=await remote.CheckConnection(r.Target);}catch(Exception ex){OutputBox.Text="Подключение к "+r.Host+" не выполнено.\n"+ex.Message+"\n\nУчётная запись приложения: "+Environment.UserDomainName+"\\"+Environment.UserName+"\nПроверьте эту учётную запись и разрешения WinRM на целевом компьютере. Команда не запускалась.";Notify("Ошибка подключения. Подробности в результате команды.");}});
 async void RunEditor_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{if(string.IsNullOrWhiteSpace(Editor.Text))throw new Exception("Введите команду.");await Submit(new(){FromEditor()});});
 async Task Guard(Func<Task> work){try{await work();}catch(Exception ex){Notify(ex.Message);MessageBox.Show(this,ex.Message,"Domain Console",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void Guard(Action work){try{work();}catch(Exception ex){Notify(ex.Message);MessageBox.Show(this,ex.Message,"Domain Console",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void Save(){Store.Write("library.json",Library.ToList());Store.Write("history.json",History.ToList());}
 ComputerRow Current()=>ComputerGrid.SelectedItem as ComputerRow??throw new Exception("Выберите компьютер.");
 List<ComputerRow> Selected(){ComputerGrid.CommitEdit();return Computers.Where(c=>c.Selected).ToList();}
 void Seed(){
  foreach(var e in new[]{("DISM CheckHealth","CMD","DISM /Online /Cleanup-Image /CheckHealth",false),("DISM ScanHealth","CMD","DISM /Online /Cleanup-Image /ScanHealth",false),("DISM RestoreHealth","CMD","DISM /Online /Cleanup-Image /RestoreHealth",true),("SFC","CMD","sfc /scannow",false),("Обновления WSUS","Updates","",false),("WindowsUpdate.log","Diagnostics","",false),("Восстановление из WIM","CMD","DISM /Online /Cleanup-Image /RestoreHealth /Source:wim:{{ImagePath}}:{{ImageIndex}} /LimitAccess",false)})Library.Add(new(){Name=e.Item1,Category="Встроенные",MicrosoftSource=e.Item4,Steps=new(){new(){Name=e.Item1,Kind=e.Item2,Code=e.Item3}}});
  Library.Add(new(){Name="DISM → SFC",Category="Встроенные",MicrosoftSource=true,Steps=new(){new(){Name="Восстановление",Code="DISM /Online /Cleanup-Image /RestoreHealth"},new(){Name="SFC",Code="sfc /scannow"}}});Save();
 }
 ComputerRow WithHistory(TargetRecord identity){var job=History.FirstOrDefault(j=>j.Targets.Any(t=>t.Host.Equals(identity.Host,StringComparison.OrdinalIgnoreCase)));var saved=job?.Targets.First(t=>t.Host.Equals(identity.Host,StringComparison.OrdinalIgnoreCase));var target=Store.Clone(identity);if(saved!=null){target.Status=saved.Status;target.State=Store.Clone(saved.State);target.Output=saved.Output;}return new(target,job?.Id??"");}
 void LoadRows(List<TargetRecord> targets){historyViewId="";loadingRows=true;try{Computers.Clear();foreach(var t in targets)Computers.Add(WithHistory(t));Tree();if(Computers.Count>0)ComputerGrid.SelectedItem=Computers[0];}finally{loadingRows=false;}ShowCurrent();RevealCurrent();}
 IEnumerable<ComputerRow> ActivePollRows()=>History.SelectMany(j=>j.Targets.Select(t=>(Job:j,Target:t))).GroupBy(x=>x.Target.Host.ToUpperInvariant()+"|"+IsWsusJob(x.Job)).Select(g=>g.First()).Where(x=>x.Target.Status is "Submitted" or "Running" or "AwaitingReboot" or "RebootScheduled").Select(x=>new ComputerRow(x.Target,x.Job.Id));
 static bool IsWsusJob(RemoteJob job)=>job.OutputChannel=="WSUS"||(job.OutputChannel==""&&job.Steps.Any(t=>t.Kind is "Updates" or "UpdateScan" or "Diagnostics"));
 RemoteJob? ChannelJob(ComputerRow row,bool wsus){var explicitJob=History.FirstOrDefault(j=>j.Id==historyViewId&&IsWsusJob(j)==wsus&&j.Targets.Any(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)));return explicitJob??History.FirstOrDefault(j=>IsWsusJob(j)==wsus&&j.Targets.Any(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)));}
 ComputerRow ExecutionRow(ComputerRow row,bool wsus){var job=ChannelJob(row,wsus);return job==null?new ComputerRow(new TargetRecord{Name=row.Name,Host=row.Host,OS=row.OS,OU=row.OU,Status="Не проверен"}):new ComputerRow(job.Targets.First(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)),job.Id);}
 ComputerRow ActiveRow()=>ExecutionRow(Current(),MainTabs.SelectedItem==WsusTab);
 bool IsCurrent(ComputerRow row)=>ComputerGrid.SelectedItem is ComputerRow current&&current.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase);
 static string CommandOutput(string output,bool wsus)=>ProgressText.Compact(wsus?output:Regex.Replace(output,@"(?m)^Отчёт WSUS:[^\r\n]*(?:\r?\n|$)",""));
 string ChannelOutput(ComputerRow row,bool wsus){var r=ExecutionRow(row,wsus);var output=!string.IsNullOrWhiteSpace(r.Target.Output)?CommandOutput(r.Target.Output,wsus):r.JobId==""?(wsus?"Для этого компьютера пока нет сохранённых заданий WSUS.":"Для этого компьютера пока нет результатов команд."):"Задание: "+r.JobId+"\nСостояние: "+r.Status+"\nОжидание результата…";return output+(servicingReports.TryGetValue(row.Host,out var diagnostic)&&!wsus?"\n\n"+diagnostic:"");}
 void ShowCurrent(){if(ComputerGrid.SelectedItem is ComputerRow r){OutputBox.Text=ChannelOutput(r,false);WsusOutput.Text=ChannelOutput(r,true);WsusServerOutput.Text=serverReports.TryGetValue(r.Host,out var report)?report:"Отчёт выбранного компьютера можно прочитать кнопкой «Прочитать отчёт сервера».";Notify(r.Name+": "+r.Status);UpdateWsusStage();}else{OutputBox.Text="Выберите компьютер или задание в истории.";WsusOutput.Text="Выберите компьютер.";Notify("Компьютер не выбран.");}}
 void OpenJob(RemoteJob job,bool showResults){historyViewId=job.Id;loadingRows=true;try{ou="";SearchBox.Text="";Computers.Clear();foreach(var t in job.Targets)Computers.Add(new(t,job.Id));Tree();if(Computers.Count>0)ComputerGrid.SelectedItem=Computers[0];}finally{loadingRows=false;}ShowCurrent();RevealCurrent();if(showResults)MainTabs.SelectedItem=IsWsusJob(job)?WsusTab:CommandsTab;}
 void History_Changed(object s,SelectionChangedEventArgs e){if(HistoryGrid.SelectedItem is RemoteJob j)Guard(()=>OpenJob(j,false));}
 async void LoadDomain_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{Notify("Загрузка AD…");var list=await Task.Run(DirectoryReader.Read);Store.Write("computers.json",list);LoadRows(list);Notify("Компьютеров: "+list.Count+". Сохранённые задания восстановлены.");});
 readonly Dictionary<string,TreeViewItem> computerNodes=new(StringComparer.OrdinalIgnoreCase);
 TreeViewItem BranchItem(string dn,string name){var members=Computers.Where(r=>dn==""||r.OU.Equals(dn,StringComparison.OrdinalIgnoreCase)||r.OU.EndsWith(","+dn,StringComparison.OrdinalIgnoreCase)).ToList();var model=new OuBranchState(dn,name,members);branches[dn]=model;var header=new Grid{MinWidth=145,DataContext=model};var bar=new ProgressBar{Height=24,Opacity=0.22,BorderThickness=new(0),Foreground=System.Windows.Media.Brushes.DodgerBlue,Background=System.Windows.Media.Brushes.Transparent};bar.SetBinding(ProgressBar.IsIndeterminateProperty,new Binding("Busy"));header.Children.Add(bar);var text=new StackPanel{Orientation=Orientation.Horizontal};text.Children.Add(new TextBlock{Text=name,Foreground=System.Windows.Media.Brushes.White});var activity=new TextBlock{Foreground=System.Windows.Media.Brushes.LightSkyBlue};activity.SetBinding(TextBlock.TextProperty,new Binding("Activity"));text.Children.Add(activity);var check=new CheckBox{Content=text,IsThreeState=true,Margin=new(3,3,3,3)};check.SetBinding(CheckBox.IsCheckedProperty,new Binding("Selected"){Mode=BindingMode.OneWay});check.Click+=(sender,args)=>SelectBranch(model);header.Children.Add(check);var item=new TreeViewItem{Header=header,Tag=model};item.SetBinding(ToolTipProperty,new Binding("Tooltip"){Source=model});return item;}
 void SelectBranch(OuBranchState branch){bool select=branch.Selected!=true;batchSelecting=true;try{foreach(var row in branch.Members)row.Selected=select;}finally{batchSelecting=false;}UpdateSelectionCount();}
 void RefreshBranches(){var active=History.SelectMany(j=>j.Targets.Select(t=>(Job:j,Target:t))).GroupBy(x=>x.Target.Host.ToUpperInvariant()+"|"+IsWsusJob(x.Job)).Select(g=>g.First()).Where(x=>x.Target.Status is "Queued" or "Sending" or "Submitted" or "Running").Select(x=>x.Target.Host).ToHashSet(StringComparer.OrdinalIgnoreCase);foreach(var branch in branches.Values)branch.Refresh(active);}
 void Tree(){
  var expanded=new HashSet<string>();void Remember(ItemsControl parent){foreach(TreeViewItem item in parent.Items){if(item.IsExpanded&&item.Tag is OuBranchState branch)expanded.Add(branch.DN);Remember(item);}}Remember(OuTree);
  OuTree.Items.Clear();computerNodes.Clear();branches.Clear();var root=BranchItem("","Весь домен");root.IsExpanded=true;OuTree.Items.Add(root);var nodes=new Dictionary<string,TreeViewItem>(StringComparer.OrdinalIgnoreCase);
  foreach(var r in Computers.OrderBy(r=>r.Name)){if(!(r.Name+" "+r.OS).Contains(SearchBox.Text,StringComparison.OrdinalIgnoreCase))continue;var parts=Regex.Split(r.OU,@"(?<!\\),");var parent=root;
   for(int i=parts.Length-1;i>=0;i--){if(!parts[i].StartsWith("OU=")&&!parts[i].StartsWith("CN="))continue;var key=string.Join(",",parts.Skip(i));if(!nodes.TryGetValue(key,out var node)){node=BranchItem(key,parts[i][3..]);node.IsExpanded=expanded.Contains(key)||SearchBox.Text.Length>0;nodes[key]=node;parent.Items.Add(node);}parent=node;}
   var header=new Grid{MinWidth=145,DataContext=r,Margin=new(0,2,0,2)};
   var bar=new ProgressBar{Height=22,Opacity=0.22,BorderThickness=new(0),Maximum=100,Background=System.Windows.Media.Brushes.Transparent,Foreground=System.Windows.Media.Brushes.DodgerBlue};bar.SetBinding(ProgressBar.ValueProperty,new Binding("Progress"){Mode=BindingMode.OneWay});bar.SetBinding(ProgressBar.IsIndeterminateProperty,new Binding("Busy"));header.Children.Add(bar);
   var check=new CheckBox{Content=r.Name,Foreground=System.Windows.Media.Brushes.White,Margin=new(3,2,3,2),ToolTip=r.Host+"\n"+r.OS};check.SetBinding(CheckBox.IsCheckedProperty,new Binding("Selected"){Mode=BindingMode.TwoWay});check.Checked+=(sender,args)=>UpdateSelectionCount();check.Unchecked+=(sender,args)=>UpdateSelectionCount();header.Children.Add(check);
   var leaf=new TreeViewItem{Header=header,Tag=r};leaf.PreviewMouseLeftButtonDown+=(sender,args)=>{leaf.IsSelected=true;ComputerGrid.SelectedItem=r;};leaf.SetBinding(TreeViewItem.ToolTipProperty,new Binding("Stage"){Source=r});parent.Items.Add(leaf);computerNodes[r.Host]=leaf;
  }
  UpdateSelectionCount();
 }
 void UpdateSelectionCount(){if(batchSelecting)return;if(SelectedLabel!=null)SelectedLabel.Text="Отмечено: "+Computers.Count(r=>r.Selected)+" / "+Computers.Count;RefreshBranches();}
