 async void Run_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{if(Steps.Count==0)throw new Exception("Последовательность пуста. Добавьте шаг или нажмите «Выполнить команду из редактора».");await Submit(Steps.ToList());});
 async Task Submit(List<CommandStep> source,string channel="Commands"){SuggestionsPopup.IsOpen=false;var selected=Selected();if(selected.Count==0||source.Count==0)throw new Exception("Выберите цели и добавьте команды.");if(!int.TryParse(LimitBox.Text,out limit)||limit<0)throw new Exception("Лимит: целое число от 0.");if(MicrosoftBox.IsChecked==true&&source.Any(x=>x.Kind is "Updates" or "UpdateScan"))throw new Exception("Разделите восстановление Microsoft и обновления WSUS.");var steps=Store.Clone(source);
  foreach(var name in Regex.Matches(string.Join("\n",steps.Select(x=>x.Code)),@"\{\{([A-Za-z][A-Za-z0-9_]*)\}\}").Select(m=>m.Groups[1].Value).Distinct()){var value=Prompt("Параметр "+name);if(value==null)return;foreach(var t in steps)t.Code=t.Code.Replace("{{"+name+"}}",value);}
  var preview="Цели: "+string.Join(", ",selected.Select(r=>r.Name))+"\nКонтекст: SYSTEM\nMicrosoft: "+MicrosoftBox.IsChecked+"\nАвтоперезагрузка: "+RebootBox.IsChecked+"\n\n"+string.Join("\n\n",steps.Select(t=>t.Name+" ["+t.Kind+"]\n"+t.Code));if(MessageBox.Show(this,preview,"Проверка задания",MessageBoxButton.OKCancel)!=MessageBoxResult.OK)return;
  historyViewId="";var job=new RemoteJob{OutputChannel=channel,Name=steps[0].Name,Steps=steps,MicrosoftSource=MicrosoftBox.IsChecked==true,AutoReboot=RebootBox.IsChecked==true,ContinueOnError=ContinueBox.IsChecked==true};foreach(var r in selected){var t=Store.Clone(r.Target);t.Status="Queued";t.State=null;t.Output="";job.Targets.Add(t);r.JobId=job.Id;queue.Enqueue((job,t));}History.Insert(0,job);if(channel=="WSUS")foreach(var r in selected)serverReports.Remove(r.Host);Save();Sync(job);ComputerGrid.SelectedItem=selected[0];MainTabs.SelectedItem=channel=="WSUS"?WsusTab:CommandsTab;ShowCurrent();SuggestionsPopup.IsOpen=false;await SendQueue();
 }
 void Sync(RemoteJob job){foreach(var row in Computers.Where(r=>r.JobId==job.Id)){var t=job.Targets.FirstOrDefault(t=>t.Host==row.Host);if(t==null)continue;row.Target.Status=t.Status;row.Target.State=t.State;row.Target.Output=t.Output;row.Refresh();}RefreshBranches();}
 async Task SendQueue(){if(sending||closing)return;sending=true;try{while(queue.Count>0&&!closing){int active=History.SelectMany(j=>j.Targets).Count(t=>t.Status is "Sending" or "Submitted" or "Running");if(limit>0&&active>=limit)break;var next=queue.Dequeue();next.Target.Status="Sending";Sync(next.Job);Save();_=SendOne(next.Job,next.Target);await Task.Delay(80);}}finally{sending=false;}}
 async Task SendOne(RemoteJob job,TargetRecord target){try{await remote.Deploy(target,job);target.Status="Submitted";target.Output="Задание передано на "+target.Host+". Ожидание результата…";}catch(Exception ex){target.Status=ex.Message.Contains("Отказано в доступе",StringComparison.OrdinalIgnoreCase)||ex.Message.Contains("Access is denied",StringComparison.OrdinalIgnoreCase)?"AccessDenied":"ConnectionFailed";target.Output="Не удалось передать задание на "+target.Host+". Выполнение команды не подтверждено.\n\n"+ex.Message+"\n\nУчётная запись приложения: "+Environment.UserDomainName+"\\"+Environment.UserName+"\nИспользуйте «Проверить подключение» для отдельной проверки WinRM.";Notify(target.Host+": ошибка подключения. Подробности в результате компьютера.");}finally{Sync(job);if(ComputerGrid.SelectedItem is ComputerRow r&&r.JobId==job.Id&&r.Host==target.Host){ShowCurrent();}Save();await SendQueue();}}
 static void Reconcile(PollResult data){var state=data.State;if(state==null)return;var failed=state.Results.LastOrDefault(r=>r.ExitCode!=0);if(failed!=null&&string.IsNullOrWhiteSpace(state.Error))state.Error="Код завершения: "+ExecutionDiagnosis.Code(failed.ExitCode)+". "+ExecutionDiagnosis.Explain(failed.ExitCode);if(state.Status=="Running"&&!string.IsNullOrWhiteSpace(state.Ended))state.Status=failed==null?"Completed":"Failed";if((state.Status is "Running" or "Queued")&&DateTimeOffset.TryParse(state.Updated,out var at)&&DateTimeOffset.UtcNow-at>TimeSpan.FromMinutes(2)&&!data.AgentAlive&&(data.TaskState is "Ready" or "Disabled")){state.Status="InterventionRequired";state.Error="Исполнитель больше не работает, но конечное состояние задания не сохранено. Планировщик: "+data.TaskState+", код задачи: "+data.TaskResult+" (0x"+unchecked((uint)data.TaskResult).ToString("X8")+"). Код задачи не является кодом DISM/SFC. Проверьте журналы; команда автоматически не перезапускается.";}}
 async Task Poll(ComputerRow row){
  var id=row.JobId;var host=row.Host;var key=id+host;if(id==""||!polling.Add(key))return;
  try{var data=await remote.Poll(row.Target,id);if(data.State!=null){
   Reconcile(data);
   var output="Компьютер: "+host+"\nСостояние: "+ComputerRow.StatusText(data.State.Status)+"\nЭтап: "+data.State.Stage+"\nШаг: "+data.State.Step+" / "+data.State.Total+"\nОбновлено: "+LocalDateConverter.Format(data.State.Updated)+(History.FirstOrDefault(j=>j.Id==id) is RemoteJob source&&IsWsusJob(source)?"\nОтчёт WSUS: "+data.State.ReportRequestStatus:"")+"\nОшибка: "+data.State.Error+"\n\n"+string.Join("\n",data.State.Results.Select(t=>t.Name+": код завершения "+ExecutionDiagnosis.Code(t.ExitCode)+(t.Error==""?"":" — "+t.Error)))+"\n\n"+ProgressText.Compact(data.Output);
   foreach(var job in History.Where(j=>j.Id==id)){var t=job.Targets.FirstOrDefault(t=>t.Host==host);if(t!=null){t.Status=data.State.Status;t.State=data.State;t.Output=output;}Sync(job);RememberSuccessful(job);}
   if(row.JobId==id){row.Target.State=data.State;row.Target.Status=data.State.Status;row.Target.Output=output;row.Refresh();if(IsCurrent(row)){ShowCurrent();Notify(row.Name+": "+row.Status);}}Save();
   if((data.State.Status is "Completed" or "AwaitingReboot" or "RebootScheduled") && History.Any(j=>j.Id==id&&j.Steps.Any(t=>t.Kind is "UpdateScan" or "Updates")) && wsusChecked.Add(key) && !string.IsNullOrWhiteSpace(WsusHost.Text))await FetchWsusReport(row);
   if(data.State.Status is "Failed" or "CompletedWithErrors" or "InterventionRequired"){if(wsusChecked.Add(key+"diagnostic")){try{var diagnostic=await remote.ServicingDiagnostics(row.Target,id);var folder=Path.Combine(Store.Root,"Diagnostics");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,row.Name+"_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".txt"),diagnostic,new UTF8Encoding(true));servicingReports[host]="--- Первичная диагностика (снимок после ошибки) ---\n"+diagnostic;if(IsCurrent(row))ShowCurrent();}catch(Exception ex){if(IsCurrent(row))Notify("Задание остановлено; диагностику получить не удалось: "+ex.Message);}}}
  }else if(IsCurrent(row)){Notify(row.Name+": результат ещё не появился на целевом компьютере; сохранённый вывод оставлен.");}}catch(Exception ex){if(IsCurrent(row))Notify(row.Name+": не удалось обновить результат; сохранённый вывод оставлен. "+ex.Message);}finally{polling.Remove(key);}
 }
 async void Refresh_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var r=ActiveRow();ShowCurrent();if(r.JobId==""){Notify("У выбранного компьютера нет задания в этом разделе. Выберите запись в истории или выполните команду.");return;}await Poll(r);});
