 void ExportCsv_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(HistoryGrid.SelectedItem is not RemoteJob j)throw new Exception("Выберите задание.");var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="results.csv"};if(d.ShowDialog(this)!=true)return;string Cell(string v)=>"\""+v.Replace("\"","\"\"")+"\"";File.WriteAllText(d.FileName,"Computer;Status;Updated;Error\r\n"+string.Join("\r\n",j.Targets.Select(t=>string.Join(";",new[]{Cell(t.Host),Cell(t.Status),Cell(t.State?.Updated??""),Cell(t.State?.Error??"")}))),new UTF8Encoding(true));});
 async void WsusClientRefresh_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var row=ExecutionRow(Current(),true);if(row.JobId=="")throw new Exception("Для этого компьютера ещё нет задания.");await Poll(row);UpdateWsusStage();});
 void UpdateWsusHeader(){WsusHeader.Text=string.IsNullOrWhiteSpace(WsusHost.Text)?"WSUS не настроен · откройте настройки":"WSUS: "+WsusHost.Text+":"+WsusPort.Text+(WsusSsl.IsChecked==true?" · HTTPS":" · HTTP");}
 WsusSettings ReadWsus(){if(!int.TryParse(WsusPort.Text,out int port)||port<1||port>65535||string.IsNullOrWhiteSpace(WsusHost.Text))throw new Exception("Укажите доменное имя сервера WSUS и порт в настройках.");var host=WsusHost.Text.Trim();if(System.Net.IPAddress.TryParse(host,out _)||host.Contains('/')||host.Contains(':'))throw new Exception("Для административного WinRM-подключения укажите доменное имя сервера без http:// и порта.");return new(){Host=host,Port=port,Ssl=WsusSsl.IsChecked==true};}
 void WsusSettings_Click(object s,RoutedEventArgs e)=>MainTabs.SelectedItem=SettingsTab;
 void SaveWsus_Click(object s,RoutedEventArgs e)=>Guard(()=>{Store.Write("wsus-settings.json",ReadWsus());UpdateWsusHeader();Notify("Настройки WSUS сохранены.");});
 void RevealCurrent(){if(ComputerGrid.SelectedItem is ComputerRow r&&computerNodes.TryGetValue(r.Host,out var leaf)){for(var parent=ItemsControl.ItemsControlFromItemContainer(leaf) as TreeViewItem;parent!=null;parent=ItemsControl.ItemsControlFromItemContainer(parent) as TreeViewItem)parent.IsExpanded=true;leaf.IsSelected=true;leaf.BringIntoView();}}
 void UpdateWsusStage(){if(ComputerGrid.SelectedItem is not ComputerRow selected){WsusStage.Text="Выберите компьютер для просмотра этапа.";return;}var r=ExecutionRow(selected,MainTabs.SelectedItem==WsusTab);var state=r.Target.State;string elapsed="";if(state!=null&&DateTimeOffset.TryParse(state.StageStarted,out var at)){var finish=DateTimeOffset.TryParse(state.Ended,out var ended)?ended:DateTimeOffset.UtcNow;var duration=finish-at;elapsed=" · этап: "+(int)duration.TotalMinutes+" мин "+duration.Seconds+" сек";if(r.Target.Status=="Running"&&duration.TotalMinutes>=5)elapsed+=" · длительное выполнение; само по себе не доказывает зависание";}if(state!=null&&r.Target.Status=="Running"){if(state.Progress.HasValue)elapsed+=" · "+(state.ProgressValue!=""?state.ProgressValue:state.Progress.ToString())+"%";if(DateTimeOffset.TryParse(state.LastOutputUtc,out var outputAt))elapsed+=" · новый вывод: "+(int)(DateTimeOffset.UtcNow-outputAt).TotalMinutes+" мин назад";if(DateTimeOffset.TryParse(state.LastProgressUtc,out var progressAt))elapsed+=" · изменение процента: "+(int)(DateTimeOffset.UtcNow-progressAt).TotalMinutes+" мин назад";if(DateTimeOffset.TryParse(state.Updated,out var heartbeat)&&DateTimeOffset.UtcNow-heartbeat>TimeSpan.FromSeconds(90))elapsed+=" · состояние агента давно не обновлялось";}WsusStage.Text=r.Name+" · "+r.Status+" · "+r.Stage+elapsed;WsusProgress.IsIndeterminate=r.Busy;WsusProgress.Value=r.Progress;CurrentComputer.Text=r.Name;CurrentDetails.Text=r.OS+" · "+r.Host;CurrentStage.Text=r.Status+" · "+r.Stage+elapsed+(state!=null&&!string.IsNullOrWhiteSpace(state.Error)?" · "+state.Error:"");CurrentProgress.IsIndeterminate=r.Busy;CurrentProgress.Value=r.Progress;}
 async Task FetchWsusReport(ComputerRow row){try{var settings=ReadWsus();var result=await remote.Wsus(settings.Host,settings.Port,settings.Ssl,row.Host);if(IsCurrent(row)){using var report=JsonDocument.Parse(result);var root=report.RootElement;string freshness="";if(DateTimeOffset.TryParse(root.GetProperty("LastReportedUtc").GetString(),out var reported)&&DateTimeOffset.TryParse(ExecutionRow(row,true).Target.State?.Started,out var started))freshness=reported>=started?"Свежий статус получен сервером после начала задания. Это проверка свежести, без привязки отчёта к конкретному запросу.":"Свежий отчёт после начала задания пока не подтверждён. Повторите чтение отчёта позже.";WsusServerOutput.Text=freshness+"\n\n"+root.GetProperty("Details").GetString();serverReports[row.Host]=WsusServerOutput.Text;Notify(row.Name+": отчёт WSUS прочитан.");}}catch(Exception ex){if(IsCurrent(row))WsusServerOutput.Text="Не удалось прочитать отчёт WSUS: "+ex.Message;}}
 async void Wsus_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{ReadWsus();WsusServerOutput.Text="Чтение отчёта сервера…";await FetchWsusReport(Current());});
 async Task WsusJob(string kind){ReadWsus();MicrosoftBox.IsChecked=false;if(kind=="UpdateScan")RebootBox.IsChecked=false;await Submit(new(){new(){Name=kind=="UpdateScan"?"WSUS · проверка и запрос отчёта":"WSUS · установка и запрос отчёта",Kind=kind}},"WSUS");MainTabs.SelectedItem=WsusTab;ShowCurrent();}
