 async void WsusInstall_Click(object s,RoutedEventArgs e)=>await Guard(async()=>await WsusJob("Updates"));
 async void WsusDiagnostics_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{MicrosoftBox.IsChecked=false;await Submit(new(){new(){Name="Диагностика WSUS клиента",Kind="PowerShell",Code="Get-ItemProperty 'HKLM:\u005cSOFTWARE\u005cPolicies\u005cMicrosoft\u005cWindows\u005cWindowsUpdate'; Get-ItemProperty 'HKLM:\u005cSOFTWARE\u005cPolicies\u005cMicrosoft\u005cWindows\u005cWindowsUpdate\u005cAU'; Get-Service wuauserv,bits; netsh winhttp show proxy; Get-WinEvent -LogName 'Microsoft-Windows-WindowsUpdateClient/Operational' -MaxEvents 30 -ErrorAction SilentlyContinue | Format-List TimeCreated,Id,LevelDisplayName,Message"},new(){Name="Сбор WindowsUpdate.log",Kind="Diagnostics"}},"WSUS");MainTabs.SelectedItem=WsusTab;});

 void OnClosing(object? s,CancelEventArgs e){if(queue.Count>0||History.SelectMany(j=>j.Targets).Any(t=>t.Status=="Sending")){if(MessageBox.Show(this,"Переданные задания продолжат работу. Закрыть командный пункт?","Закрытие",MessageBoxButton.YesNo)!=MessageBoxResult.Yes){e.Cancel=true;return;}}closing=true;timer.Stop();SaveCommandLayout();Save();}
}

public sealed class CommandLayout {public double EditorRatio {get;set;}=0.24;}
public sealed class CommandSuggestion {public LibraryEntry Entry {get;set;}=new();public string Source {get;set;}="";public string Name=>Entry.Name;public string Detail=>Source+" · "+string.Join(" / ",Entry.Steps.Select(t=>t.Kind).Distinct())+(Entry.Steps.Count>1?" · шагов: "+Entry.Steps.Count:"");public string Preview=>string.Join("\n\n",Entry.Steps.Select(t=>t.Code));}
